from kd_common import *
i=6
Z=lambda q,a:[('z',q),('b',a)]
def plan():
    o='<rect x="80" y="30" width="400" height="190" fill="#e9d6c0" stroke="#7a3b1f" stroke-width="4"/>'
    o+='<rect x="210" y="80" width="140" height="90" fill="#f7ead2" stroke="#7a3b1f" stroke-width="2"/>'+T(280,128,'central hall',10)
    o+=g(280,110,.5,hanging_lamp())+'<rect x="90" y="40" width="100" height="60" fill="#f7ead2" stroke="#7a3b1f" stroke-width="2"/>'+T(140,74,'prayer corner',9)
    o+='<rect x="370" y="40" width="100" height="60" fill="#f7ead2" stroke="#7a3b1f" stroke-width="2"/>'+T(420,74,'granary',9)
    o+='<rect x="80" y="190" width="400" height="30" fill="#d9c2a0"/>'+T(280,210,'verandah',10)+'<rect x="500" y="80" width="40" height="40" fill="#cfc0a0"/>'+T(520,134,'kaimaḍa',9)
    return o+T(280,246,'simplified; layouts vary by house',9)
fw=foreword(i,['Every Kodava clan has one house that is more than a house: the <b>ainmane</b>, the ancestral home of the okka. It may be a hundred years old or several hundred; most of the family may live in Bengaluru or Dubai; but at Puttari and Kailpoḷd, at weddings and deaths, they come back to it, and before its <b>hanging lamp</b> the family prays.',
 'This part explains what the ainmane is, how it is built and arranged, the lamp and the prayer corner, the kaimaḍa for the ancestor, who heads the house, and why the clans are restoring their houses.',
 'The clans and the guru kāraṇa were introduced in '+L('/kodagu/kodavas/','Part 1')+'. Previous: '+L('/kodagu/mand-and-dances/','the mand')+'. Next: '+L('/kodagu/life-rites/','life rites')+'.'],Z('Why “ain”?','Commonly explained as “ancestral” or “main” house. Spellings: ainmane, ain mane, aimane.'))
gl=glance([('What','The ancestral house of a Kodava clan (okka)'),('Who','All members of the okka share it'),('Head','The paṭṭedāra, the elder of the house'),('Heart','The central hall with the sacred hanging lamp'),('Ancestor','The guru kāraṇa, honoured at the kaimaḍa'),('Rites','Festivals, weddings, deaths, clan meetings'),('Built','Wood, laterite and mud, with tiled roofs'),('Also','Many Kodava-speaking communities have ainmanes'),('Today','Many restored by clan trusts'),('Festivals',L('/kodagu/puttari/','Puttari')+', '+L('/kodagu/kailpodh/','Kailpoḷd'))],
 S('A large tiled-roof ancestral house with a courtyard and a small shrine beside it',g(280,210,1.8,ainmane(200))+g(490,210,1,'<rect x="-24" y="-40" width="48" height="40" fill="#e9d6c0"/><path d="M-30 -40 l30 -20 l30 20z" fill="#7a3b1f"/>'),'#d8e8c8',215),Z('Does anyone live there?','Often a branch of the family does. Others come for festivals.'),'One house <b>for a whole clan</b>.')
what=reading('what','WHAT IT IS','The clan’s home',S('A family tree whose branches all return to a house',g(280,210,1.4,ainmane())+''.join(f'<path d="M{60+k*110} 60 C{60+k*110} 120 280 100 280 150" stroke="#8a6a3a" stroke-width="3" fill="none"/>'+g(60+k*110,60,.6,person(['#c0392b','#1d4f8a','#2a9d6f','#e0a800','#6a3d9a'][k])) for k in range(5)),'#fff3cf',215),
 ['<b>Ainmane.</b> The ancestral home of an okka, where the clan began in a place.','<b>Shared.</b> It belongs to the whole clan, not to one heir.','<b>Clan name.</b> Every member carries the okka name, and the house is where that name lives.','<b>Rights.</b> A bride receives rights in her husband’s ainmane at the wedding (see '+L('/kodagu/life-rites/','Part 8')+').','<b>Many communities.</b> Most Kodava-speaking communities have ainmanes too.'],Z('Like a family temple?','House, temple and meeting hall in one.'),'House, temple <b>and meeting hall</b>.')
plan_=reading('plan','INSIDE','How the house is arranged',svg(560,260,'Simplified plan of an ainmane with central hall and lamp, prayer corner, granary, verandah and kaimaḍa',plan()),
 ['<b>Central hall.</b> The heart is the main hall where the sacred lamp hangs; here rites are performed.','<b>Prayer corner.</b> A corner or room is kept for prayer, for the ancestors and for Kāverī.','<b>Stores.</b> Granaries and store rooms held the paddy of the estate.','<b>Verandah.</b> A long verandah opens to the courtyard where guests are received.','<b>Names.</b> Kodava names for the rooms vary by house and region; we keep to English here.'],Z('All ainmanes look like this?','No. This is only the idea. Old houses grew room by room.'),'Built around <b>the lamp</b>.')
build_=reading('build','BUILT TO LAST','Wood, laterite and tile',S('Carved wooden pillars and a sloping tiled roof against the rain',g(280,190,1.8,ainmane(220))+''.join(f'<rect x="{170+k*60}" y="140" width="10" height="70" fill="#5a3a1a"/>' for k in range(4))+''.join(f'<path d="M{x} 20 l-6 14" stroke="#4aa3df" stroke-width="2"/>' for x in range(40,540,40)),'#d8e8f0',230),
 ['<b>For rain.</b> Steep tiled roofs shed the monsoon.','<b>Wood.</b> Pillars, doors and ceilings are of local timber, often carved.','<b>Walls.</b> Thick walls of mud and laterite keep the house cool and dry.','<b>Courtyard.</b> Many houses are built around or before an open courtyard.','<b>Repairs.</b> Clans pool money to repair the roof and woodwork.'],Z('How old are they?','Some claim many centuries. Most standing houses were rebuilt in the 19th and 20th centuries.'),'A house <b>for heavy rain</b>.')
lamp_=reading('lamp','THE LAMP','The light that hangs in the hall',S('A tall brass hanging lamp with flames before the family',g(280,215,2.4,hanging_lamp())+g(120,215,1.2,kodava_man())+g(440,215,1.2,kodava_woman()),'#20243a',230),
 ['<b>The lamp.</b> A brass lamp hangs in the central hall; it is lit for every rite.','<b>Before it.</b> Prayers to the ancestors are said before the lamp, not before an idol.','<b>Weddings.</b> At a Kodava wedding, elders bless the couple before the lamp; there is no fire ritual and no priest.','<b>Puttari.</b> The Puttari procession leaves from and returns to the lamp.','<b>Kailpoḷd.</b> Weapons are laid before it.'],Z('No idol?','In many ainmanes, no. The lamp and the ancestors are enough.'),'Pray <b>before the light</b>.')
kaimada=reading('kaimada','THE KAIMAḌA','The ancestor’s shrine',S('A small shrine beside the house with a lamp and offerings',g(380,210,1.2,ainmane(160))+g(130,210,1.4,'<rect x="-30" y="-50" width="60" height="50" fill="#e9d6c0"/><path d="M-36 -50 l36 -24 l36 24z" fill="#7a3b1f"/>'+g(0,-10,.6,lamp()))+g(200,210,.8,plate()),'#fff3cf',215),
 ['<b>Guru kāraṇa.</b> The founding ancestor of the family is the guru kāraṇa.','<b>Kaimaḍa.</b> He is honoured at a small shrine, the kaimaḍa, near the house.','<b>Offerings.</b> Annual offerings are made, with family food.','<b>Kāraṇas.</b> Ancestors are believed to protect the descendants who remember them.','<b>At festivals.</b> Every festival begins with remembering them.'],Z('Do all houses have one?','Many do; customs differ between families.'),'The founder <b>has his own house</b>.')
head=reading('head','THE PAṬṬEDĀRA','Who leads the house',S('An elder seated, family around him, a lamp behind',g(280,215,1.6,kodava_man('#f4f1ea'))+g(280,100,.8,hanging_lamp())+''.join(g(x,215,1,c) for x,c in [(130,kodava_woman()),(190,kodava_man()),(380,kodava_man()),(440,kodava_woman('#2a9d6f'))]),'#fff3cf',215),
 ['<b>Paṭṭedāra.</b> The head of the house, usually the senior male, is the paṭṭedāra.','<b>Duties.</b> He leads rites: lighting the lamp, offerings, the Puttari procession.','<b>Clan meetings.</b> Family matters are discussed at the ainmane.','<b>Elders.</b> Family elders, not priests, guide weddings and deaths.','<b>Today.</b> Clan associations often manage the house and its trust.'],Z('What if he lives abroad?','Another elder leads, or he flies home for Puttari.'),'An elder, <b>not a priest</b>.')
gather=reading('gather','COMING HOME','Festivals at the ainmane',S('Cars parked beside an old house; families in traditional dress greet each other',g(280,200,1.4,ainmane())+''.join(g(100+k*80,215,.9,[kodava_man(),kodava_woman(),person('#1d4f8a'),kodava_man('#3a3a3a'),kodava_woman('#2a9d6f')][k]) for k in range(5))+'<rect x="440" y="190" width="70" height="24" rx="6" fill="#3a6aa0"/>','#d8e8c8',215),
 ['<b>Puttari.</b> At harvest the whole okka gathers at the ainmane.','<b>Kailpoḷd.</b> Weapons are worshipped in the hall.','<b>Weddings.</b> Rites of welcome and rights are performed here.','<b>Deaths.</b> Final rites link the dead to the ancestors.','<b>Reunions.</b> Clan days bring scattered families together.'],Z('Do the young come?','They come for Puttari. The food helps.'),'The clan <b>comes home</b>.')
rest=reading('restore','RESTORING','Saving the old houses',S('Workers repairing a tiled roof while elders watch',g(280,200,1.6,ainmane())+g(220,110,.8,person('#e0a800'))+g(330,110,.8,person('#e0a800'))+g(120,215,1,kodava_man())+g(450,215,1,kodava_man('#3a3a3a')),'#d8e8c8',215),
 ['<b>Decay.</b> Many ainmanes fell into disrepair as families moved away.','<b>Trusts.</b> Clan trusts and associations raise funds for repair and rebuilding.','<b>Choices.</b> Some restore old woodwork; others rebuild in concrete with the old plan.','<b>Records.</b> Families record their histories and photographs.','<b>Identity.</b> Restoring the house is restoring the clan.'],Z('Concrete or wood?','A hot debate in every okka.'),'Save the house, <b>save the clan</b>.')
endp=end(i,['<b>What.</b> The ancestral house of a Kodava clan.','<b>Heart.</b> The central hall and its hanging lamp.','<b>Ancestor.</b> The guru kāraṇa at the kaimaḍa.','<b>Head.</b> The paṭṭedāra, with the elders.','<b>Life.</b> Festivals, weddings, deaths and restoration.'],'Part 8 is life rites.','Before the lamp')
src=sources([('House:','Wikipedia “Kodava people” (okka, ainmane, guru kāraṇa, kaimaḍa); Kodagu First (ainmanes of Kodava-speaking communities); accounts of weddings before the lamp (Coorg Tourism Info, The Knot); Puttari accounts (Star of Mysore, Deccan Herald).')],'room names are omitted because they vary; ages of houses are generalised; restoration trends are a general observation.','Kodava terms romanised simply.')
finish(i,'PART 7 OF 12 · HOUSE · LAMP · ANCESTOR',covart('An old ancestral house with a brass lamp glowing in its hall',g(220,190,1.5,ainmane(200))+g(220,120,.6,hanging_lamp())),'Before the lamp',
 'The <b>ainmane</b>, the ancestral house of a Kodava clan: its plan, the <b>hanging lamp</b>, the kaimaḍa of the founding ancestor, the paṭṭedāra and the festivals that bring the clan home.',
 'The Kodava ainmane explained and illustrated: the clan’s ancestral house, its layout and building, the sacred hanging lamp, the kaimaḍa and guru kāraṇa, the paṭṭedāra, festivals and restoration.',
 [fw,gl,what,plan_,build_,lamp_,kaimada,head,gather,rest,endp,src])
